using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() => Type: {typeInfo.Type.Name}, Properties: {typeInfo.Properties.Count}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// Case A: type metadata IS available (default resolver handles any type)
if (options.TryGetTypeInfo<Person>(out var info))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {info!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// Case B: options with a custom resolver that only knows about Person
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};

if (limited.TryGetTypeInfo<Person>(out var personInfo))
    Console.WriteLine($"TryGetTypeInfo<Person> on limited resolver succeeded: {personInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> on limited resolver returned false");

if (limited.TryGetTypeInfo<int>(out var intInfo))
    Console.WriteLine($"TryGetTypeInfo<int> on limited resolver succeeded: {intInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<int> on limited resolver returned false (no exception!)");

// --- Types ---
public record Person(string Name, int Age);

// A resolver that only resolves Person, returns null for everything else.
file class LimitedResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return JsonMetadataServices.CreateObjectInfo<Person>(options, new JsonObjectInfoValues<Person>());
        return null;
    }
}

